/**
 * @brief Emit a unary instruction with its planned destination.
 *
 * @param out Target output stream.
 * @param placement Placement information indexed by IR value ID.
 * @param opcode IFJcode26 instruction mnemonic.
 * @param inst IR instruction being analyzed or emitted.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
static void cg_print_unary_inst(FILE* out,
                                const CgPlacement* placement,
                                char* opcode,
                                IrInstruction* inst) {
  if (inst->result == IR_INVALID_ID)
    return;
  fputs(opcode, out);
  cg_print_ws(out);
  cg_print_value(out, placement, inst->result);
  cg_print_ws(out);
  cg_print_operand(out, placement, &inst->operands.unary.operand);
  cg_print_nl(out);
}

// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
void cg_print_binary_inst(FILE* out,
                          const CgPlacement* placement,
                          char* opcode,
                          IrInstruction* inst) {
if (inst->result == IR_INVALID_ID && strcmp(opcode, "DIV") != 0 &&
      strcmp(opcode, "IDIV") != 0)
    return;
  fputs(opcode, out);
  cg_print_ws(out);
  if (inst->result == IR_INVALID_ID) {
    fputs("GF@$tmp1", out);
  } else {
    cg_print_value(out, placement, inst->result);
  }
  cg_print_ws(out);
  cg_print_operand(out, placement, &inst->operands.binary.left);
  cg_print_ws(out);
  cg_print_operand(out, placement, &inst->operands.binary.right);
  cg_print_nl(out);
}

/**
 * @brief Negate a Boolean in its existing destination to avoid a temporary.
 *
 * @param out Target output stream.
 * @param placement Placement information indexed by IR value ID.
 * @param result IR value ID of the Boolean result.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
static void cg_print_not_result(FILE* out,
                                const CgPlacement* placement,
                                size_t result) {
  if (result == IR_INVALID_ID)
    return;
  fputs("NOT ", out);
  cg_print_value(out, placement, result);
  cg_print_ws(out);
  cg_print_value(out, placement, result);
  cg_print_nl(out);
}

/**
 * @brief Emit floor using integer truncation and a correction for negative
 * fractions.
 *
 * @param ctx Compiler context.
 * @param out Target output stream.
 * @param placement Placement information indexed by IR value ID.
 * @param inst IR instruction being analyzed or emitted.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "In C:\Users\wwwho\Downloads\IFJ26\knowledge, you have details about
// this project. Everything should be implemented, except a portion of lowering.
// Finish its implementation. Match the style how optimizer was written, split
// code into meaningful commits. Before committing each commit stop and wait for
// my confirmation."
// Changes: Emit floor with a Double result.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Thread value placement through this emitter.
static void cg_print_floor(Ctx* ctx,
                           FILE* out,
                           const CgPlacement* placement,
                           IrInstruction* inst) {
  if (inst->result == IR_INVALID_ID)
    return;

  IrValueId result = inst->result;
  size_t label = ++ctx->cg_state.builtin_label_id;
  IrOperand* operand = &inst->operands.unary.operand;

  // The target conversion truncates toward zero. Convert back to Double
  // and subtract one only when truncation rounded toward positive infinity.
  fputs("FLOAT2INT GF@$tmp1 ", out);
  cg_print_operand(out, placement, operand);
  cg_print_nl(out);

  fprintf(out, "INT2FLOAT LF@val_%zu GF@$tmp1\n", result);
  fprintf(out, "GT GF@$tmp1 LF@val_%zu ", result);
  cg_print_operand(out, placement, operand);
  cg_print_nl(out);

  fprintf(out, "JUMPIFNEQ $cg_floor_end_%zu GF@$tmp1 bool@true\n", label);
  fprintf(out, "SUB LF@val_%zu LF@val_%zu float@0x1p+0\n", result, result);
  fprintf(out, "LABEL $cg_floor_end_%zu\n", label);
}

