// Changes: Thread function type information into builtin generation.
// Thread value placement through this emitter.
// Keep inclusive Double comparisons false on unordered operands.
bool cg_ordered_inclusive(IrFunction* fn, const IrInstruction* inst) {
  return (inst->type == IR_INST_LE || inst->type == IR_INST_GE) &&
         cg_operand_type(fn, &inst->operands.binary.left) == IR_DOUBLE;
}

/**
 * @brief Emit an inclusive comparison with the target's ordered comparison
 * semantics.
 *
 * @param ctx Compiler context.
 * @param out Target output stream.
 * @param placement Placement information indexed by IR value ID.
 * @param fn IR function being analyzed or emitted.
 * @param inst IR instruction being analyzed or emitted.
 */
static void cg_print_inclusive(Ctx* ctx,
                               FILE* out,
                               const CgPlacement* placement,
                               IrFunction* fn,
                               IrInstruction* inst) {
  if (inst->result == IR_INVALID_ID)
    return;

  if (!cg_ordered_inclusive(fn, inst)) {
    cg_print_binary_inst(out, placement, inst->type == IR_INST_LE ? "GT" : "LT",
                         inst);
    cg_print_not_result(out, placement, inst->result);
    return;
  }

  size_t label = ++ctx->cg_state.builtin_label_id;
  cg_print_binary_inst(out, placement, inst->type == IR_INST_LE ? "LT" : "GT",
                       inst);
  fprintf(out, "JUMPIFEQ $cg_inclusive_%zu ", label);
  cg_print_value(out, placement, inst->result);
  fputs(" bool@true\n", out);
  cg_print_binary_inst(out, placement, "EQ", inst);
  fprintf(out, "LABEL $cg_inclusive_%zu\n", label);
}

bool cg_uses_stack_return(const Ctx* ctx, IrFunctionId fid) {
  return ctx->cg_state.return_modes[fid] == CG_RETURN_USED;
}

void cg_generate_instruction(Ctx* ctx,
                             FILE* out,
                             const CgPlacement* placement,
                             IrFunction* fn,
                             IrInstruction* inst) {
  switch (inst->type) {
    case IR_INST_ADD:
      cg_print_binary_inst(out, placement, "ADD", inst);
      break;
    case IR_INST_SUB:
      cg_print_binary_inst(out, placement, "SUB", inst);
      break;
    case IR_INST_MUL:
      cg_print_binary_inst(out, placement, "MUL", inst);
      break;
    case IR_INST_DIV:
      cg_print_binary_inst(out, placement, "DIV", inst);
      break;
    case IR_INST_IDIV:
      cg_print_binary_inst(out, placement, "IDIV", inst);
      break;
    case IR_INST_FLOOR:
      cg_print_floor(ctx, out, placement, inst);
      break;
    case IR_INST_CONCAT:
      cg_print_binary_inst(out, placement, "CONCAT", inst);
      break;
    case IR_INST_NOT:
      cg_print_unary_inst(out, placement, "NOT", inst);
      break;
    case IR_INST_INT2DOUBLE:
      cg_print_unary_inst(out, placement, "INT2FLOAT", inst);
      break;
    case IR_INST_EQ:
      cg_print_binary_inst(out, placement, "EQ", inst);
      break;
    case IR_INST_LT:
      cg_print_binary_inst(out, placement, "LT", inst);
      break;
    case IR_INST_GT:
      cg_print_binary_inst(out, placement, "GT", inst);
      break;
    case IR_INST_NE:
      cg_print_binary_inst(out, placement, "EQ", inst);
      cg_print_not_result(out, placement, inst->result);
      break;
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Implement all"
    // Changes: Use ordered semantics for materialized inclusive comparisons.
    case IR_INST_LE:
    case IR_INST_GE:
      cg_print_inclusive(ctx, out, placement, fn, inst);
      break;
    case IR_INST_LOAD:
      if (inst->result == IR_INVALID_ID)
        break;
      fputs("MOVE ", out);
      cg_print_value(out, placement, inst->result);
      cg_print_ws(out);
      cg_print_localframe_slot(out, inst->operands.load.source);
      cg_print_nl(out);
      break;
    case IR_INST_STORE:
      fputs("MOVE ", out);
      cg_print_localframe_slot(out, inst->operands.store.target);
      cg_print_ws(out);
      cg_print_operand(out, placement, &inst->operands.store.source);
      cg_print_nl(out);
      break;
    case IR_INST_CALL:
      if (inst->operands.call.type == IR_FX_USER) {
        fputs("CREATEFRAME", out);
        cg_print_nl(out);

        for (size_t i = 0; i < inst->operands.call.arg_count; i++) {
          fputs("DEFVAR ", out);
          cg_print_tempframe_slot(out, i);
          cg_print_nl(out);
          fputs("MOVE ", out);
          cg_print_tempframe_slot(out, i);
          cg_print_ws(out);
          cg_print_operand(out, placement, &inst->operands.call.args[i]);
          cg_print_nl(out);
        }

        fputs("CALL $$", out);
        fputs(ctx->ir.functions.data[inst->operands.call.id].name, out);
        cg_print_nl(out);

        if (inst->result != IR_INVALID_ID) {
          IrFunction* callee = &ctx->ir.functions.data[inst->operands.call.id];
          // AI generated by: Codex (GPT-6.2-sol)
          // Prompt: "Implement all"
          // Changes: Pop a stack return directly into its planned destination.
          if (cg_uses_stack_return(ctx, inst->operands.call.id)) {
            fputs("POPS ", out);
            cg_print_value(out, placement, inst->result);
            cg_print_nl(out);
            break;
          }
          fputs("MOVE ", out);
          cg_print_value(out, placement, inst->result);
          if (callee->return_type == IR_UNIT) {
            fputs(" nil@nil", out);
          } else {
            fputs(" TF@%ret", out);
          }
          cg_print_nl(out);
        }
      } else {
        // AI generated by: Codex (GPT-6.2-sol)
        // Prompt: "Implement all"
        // Changes: Pass the current function to typed builtin selection.
        cg_print_builtin(ctx, out, placement, fn, inst);
      }
      break;
  }
}
